/* Japanese bitmap font for the System Card's font call (EX_GETFNT): Shinonome Gothic 12x12
 * and 16x16 (public domain), for the JIS rows the System Card has: 0x21-0x27 and 0x30-0x4F.
 * Data generated by tools/fonts/make_kanji_font.py. */
#pragma once

#include <stdint.h>

#define KANJI_CELLS (39 * 94)

/* 12x12: 12 rows of 12 bits, two rows in three bytes; 16x16: 16 rows of two bytes. The
 * leftmost pixel is the high bit. Empty cells are all zero. */
extern const uint8_t kanji_font12[KANJI_CELLS][18];
extern const uint8_t kanji_font16[KANJI_CELLS][32];

/* Cell of a JIS code (row and column 0x21-0x7E), or -1 if the System Card has no glyph there. */
static inline int kanji_cell(int row, int col)
{
    if (col < 0x21 || col > 0x7E) return -1;
    if (row >= 0x21 && row <= 0x27) return (row - 0x21) * 94 + (col - 0x21);
    if (row >= 0x30 && row <= 0x4F) return (row - 0x30 + 7) * 94 + (col - 0x21);
    return -1;
}
